package com.example.survivor.game;

import java.util.Scanner;

/** An optional, resumable conversation after the intact box has been returned. */
final class AndreyCampfire {
    private AndreyCampfire(){}
    static boolean available(ForestStories story){return story.andrey==3 && story.questStarted && story.boxState==1 && !story.boxOpened;}
    static boolean heardRadio(Fighter p,WorldStories w){return w.radioOpeningHeard()||p.getUpgrades().signalReceived;}
    private static void say(String title,String text,Scanner scanner){ResidentialStories.pause(title,text,scanner);}
    private static void record(ForestStories story,WorldStories w,int topic,int choice){
        if(story.campfireAnswers==null)story.campfireAnswers=new int[5];
        story.campfireAnswers[topic-1]=choice;story.campfireTopics|=1<<(topic-1);w.advanceMinutes(4);GameIO.checkpoint();
    }
    private static boolean done(ForestStories story,int topic){return (story.campfireTopics&(1<<(topic-1)))!=0;}
    static void open(ForestStories story,Fighter p,WorldStories w,Scanner scanner){
        if(!available(story)){GameIO.out().println("Андрей пока не готов к этому разговору.");return;}
        if(!story.campfireIntro){
            GameIO.storyMenu("Пока горит костёр","Андрей убирает снасти под навес и долго рассматривает возвращённую фотографию: на ней он с молодым мужчиной у озера.\n\n«Я уж думал, не увижу эту штуку. Там не сами снасти важны, понимаешь? Ты не спешишь? Чай у меня, правда, дрянной. Но горячий».\n\nДжон садится на поваленное бревно и берёт металлическую кружку. Андрей смотрит на огонь: «Раньше здесь отдыхающие песни орали до трёх ночи. А теперь даже поговорить не с кем».");
            GameIO.action(1,"Иногда тишина лучше людей");GameIO.action(2,"Мне тоже не хватает обычных разговоров");GameIO.action(3,"Не привык задерживаться на одном месте");GameIO.action(4,"А кто на фотографии?");GameIO.action(0,"Поговорим в другой раз");
            int c=SurvivalSystems.choice(scanner);if(c<1||c>4)return;
            story.campfireIntro=true;story.talked=true;story.campfireIntroChoice=c;w.advanceMinutes(4);
            w.note("Пока горит костёр","Андрей пригласил Джона задержаться у костра после возвращения ящика. Разговор можно продолжить при следующем посещении.");GameIO.checkpoint();
            String[] reply={"","Андрей кивает: «Бывает. Только иногда её становится слишком много».","«Вот и мне», — отвечает Андрей и протягивает кружку поближе.","«Не держу. Можешь уйти, когда захочешь», — отвечает Андрей.","Андрей убирает фотографию в карман. «Брат. Потом расскажу»."};
            say("У костра",reply[c]+"\n\n«Ну а ты? Откуда сам? Чем жил до всего этого?»",scanner);
        }
        while(p.isAlive()&&available(story)){
            GameIO.storyMenu("Пока горит костёр","Можно выбрать любую тему, отложить разговор или закончить его. Обсуждённые темы сохраняются.");
            GameIO.action(1,"Кем ты был раньше?",done(story,1)?"Уже обсудили":"",!done(story,1));
            GameIO.action(2,"Ты кого-нибудь потерял?",done(story,2)?"Уже обсудили":"",!done(story,2));
            GameIO.action(3,"Зачем ты продолжаешь?",done(story,3)?"Уже обсудили":"",!done(story,3));
            GameIO.action(4,"Другие выжившие",done(story,4)?"Уже обсудили":"",!done(story,4));
            GameIO.action(5,"Чего тебе не хватает?",done(story,5)?"Уже обсудили":"",!done(story,5));
            GameIO.action(6,story.campfireEnded?"Закончить разговор":"Попрощаться у костра");GameIO.action(0,"Продолжить в другой раз");
            int topic=SurvivalSystems.choice(scanner);if(topic==0)return;
            if(topic==6){finish(story,w,scanner);return;}
            if(topic<1||topic>5||done(story,topic))continue;
            if(topic==1)past(story,w,scanner);else if(topic==2)brother(story,w,scanner);else if(topic==3)purpose(story,p,w,scanner);else if(topic==4)people(story,w,scanner);else ordinary(story,w,scanner);
        }
    }
    private static void past(ForestStories s,WorldStories w,Scanner scanner){
        GameIO.storyMenu("Кем ты был раньше?","Андрей: «Ну а ты? Откуда сам? Чем жил до всего этого?»");
        GameIO.action(1,"Работа, дом и снова работа");GameIO.action(2,"Я и раньше был один");GameIO.action(3,"Не хочу вспоминать");GameIO.action(4,"Зомби хотя бы добавили разнообразия");GameIO.action(0,"Выбрать другую тему");
        int c=SurvivalSystems.choice(scanner);if(c<1||c>4)return;record(s,w,1,c);
        String[] text={"","Джон: «Работал. Домой приходил, ел, спал. На следующий день всё заново. Иногда казалось, что жизнь мимо проходит».\n\nАндрей: «А теперь что скажешь?»\nДжон: «Теперь бы хоть на один такой день вернуться».\nАндрей смотрит на кружку: «Раньше скучали от спокойствия. А теперь за него всё отдали бы».",
        "Джон: «Да особо никого рядом не было. Я и раньше большую часть времени один проводил».\nАндрей: «Значит, тебе проще».\nДжон: «Я тоже так думал».\nАндрей: «Одиночество хорошее, пока знаешь, что можешь его прекратить. Когда выбирать больше не из кого, оно другое».",
        "Джон: «Не хочу вспоминать».\nАндрей кивает и поправляет полено: «И не надо. Иногда начинаю рассказывать, а потом сам жалею. Думал, слова облегчают. Не всегда. Захочешь — сам расскажешь».",
        "Джон: «Жизнь моя была довольно скучной. Зомби хотя бы разнообразия добавили».\nАндрей коротко смеётся: «Я бы всё-таки предпочёл скучать».\nДжон: «А ты кем работал?»\nАндрей: «Лесником. Теперь, считай, повысили. Весь лес мой. Зарплату только задерживают»."};say("Кем ты был раньше?",text[c],scanner);
    }
    private static void brother(ForestStories s,WorldStories w,Scanner scanner){
        GameIO.storyMenu("Фотография","Андрей достаёт фотографию. «С братом мы в последний раз разговаривали за неделю до всего этого. Поругались из-за ерунды: он хотел продать отцовскую лодку, а я был против».\n\nОн поворачивает кружку в руках. «Если он жив, вспоминает ли вообще эту ссору? Или только я тут сижу, сам себя грызу?»");
        GameIO.action(1,"Сейчас ссора для него вряд ли важна");GameIO.action(2,"Надо было мириться раньше");GameIO.action(3,"Я тоже оставил кое-что недосказанным");GameIO.action(4,"Не стоит хоронить его раньше времени");GameIO.action(5,"Промолчать");GameIO.action(0,"Выбрать другую тему");
        int c=SurvivalSystems.choice(scanner);if(c<1||c>5)return;record(s,w,2,c);
        w.note("Фотография Андрея","Андрей рассказал о брате и их последней ссоре. Судьба брата неизвестна.");GameIO.checkpoint();
        String[] reply={"","Андрей долго смотрит на огонь. «Может, ты и прав. Хотелось бы однажды спросить у него самого».","Андрей опускает голову. «Знаю. Каждый день себе это повторяю. Но ты ведь не знаешь, когда разговариваешь с человеком в последний раз».","«Тогда понимаешь», — тихо говорит Андрей. «Самое паршивое, что теперь даже не знаешь, кому эти слова говорить».","Андрей кивает. «Вот поэтому я и храню фотографию. Пока не знаю наверняка, буду считать, что он где-то есть».","Некоторое время оба молча смотрят на угли. «Ладно. Не будем о грустном весь вечер», — говорит Андрей."};say("Фотография",reply[c],scanner);
    }
    private static void purpose(ForestStories s,Fighter p,WorldStories w,Scanner scanner){
        GameIO.storyMenu("Зачем ты продолжаешь?","Костёр затухает, Андрей подбрасывает сухие ветки. «Ты ведь каждый день рискуешь, всё что-то ищешь. Ради чего? Просто чтобы завтра опять проснуться и делать то же самое?»");
        if(heardRadio(p,w))GameIO.action(1,"Хочу проверить сообщение об эвакуации");
        GameIO.action(2,"Просто не хочу умирать");GameIO.action(3,"Надеюсь найти людей");GameIO.action(4,"Честно говоря, уже не понимаю");GameIO.action(5,"Хочу однажды снова жить нормально");GameIO.action(0,"Выбрать другую тему");
        int c=SurvivalSystems.choice(scanner);if(c<1||c>5||c==1&&!heardRadio(p,w))return;record(s,w,3,c);
        String[] text={"","Джон: «Я слышал по радио сообщение об эвакуации. Говорили, через тридцать дней будут забирать выживших. Не знаю, правда это или нет, но хочу проверить».\nАндрей задумывается: «Я тоже когда-то слышал подобное. Только сигнал пропал, и я перестал искать. Если узнаешь что-нибудь наверняка, расскажи. Может, и мне ещё есть куда идти».",
        "Джон: «Не знаю. Наверное, просто не хочу умирать».\nАндрей улыбается: «Справедливо. Я тут тоже не из-за большой любви к консервам сижу. Иногда одного упрямства хватает, чтобы протянуть ещё день».",
        "Джон: «Надеюсь найти кого-нибудь. Не хочу до конца жизни разговаривать только с собственным отражением».\nАндрей: «Людей найдёшь. Только осторожнее. Иногда лучше встретить одного нормального человека за месяц, чем десятерых за день». Он делает паузу: «Хотя сегодня мне повезло».",
        "Джон: «Если честно, сам уже не понимаю. Просыпаюсь, ищу еду, лечу раны. Иногда кажется, что всё это ни к чему».\nАндрей перестаёт улыбаться: «Понимаю. Бывают дни, когда даже костёр разводить не хочется. Я стараюсь не думать обо всём сразу. Сегодня поел, воды набрал, крышу починил — значит, день прожит не зря». Он подвигает Джону кружку: «На сегодня хотя бы посиди спокойно».",
        "Джон: «Хочу когда-нибудь снова жить нормально. Дом, горячая вода, возможность выйти на улицу без оружия».\nАндрей: «Хороший план. Я бы добавил рыбалку — когда рыба нужна не для того, чтобы не умереть с голоду, а просто потому, что захотелось посидеть у воды»."};say("Зачем ты продолжаешь?",text[c],scanner);
    }
    private static void people(ForestStories s,WorldStories w,Scanner scanner){
        GameIO.storyMenu("Другие выжившие","Андрей вспоминает троих незнакомцев: «Попросили воды. Я дал. Потом один начал расспрашивать, где у меня запасы. Я сказал, что их почти нет. Они ушли, а я полдня думал, правильно ли поступил».");
        GameIO.action(1,"Доверять сейчас никому нельзя");GameIO.action(2,"Нужно помогать, пока можешь");GameIO.action(3,"Я бы предложил обмен");GameIO.action(4,"Ты хотя бы дал им воды");GameIO.action(5,"В следующий раз не открывай дверь");
        ResidentialStories r=w.residential();if(r.family==2||r.family==3||r.family==7)GameIO.action(6,"Вспомнить Марину и её сына");if(r.kirill==2)GameIO.action(7,"Рассказать о Кирилле");if(r.viktor==2)GameIO.action(8,"Рассказать о Викторе Павловиче");GameIO.action(0,"Выбрать другую тему");
        int c=SurvivalSystems.choice(scanner);if(c<1||c>8||c==6&&!(r.family==2||r.family==3||r.family==7)||c==7&&r.kirill!=2||c==8&&r.viktor!=2)return;record(s,w,4,c);
        String[] text={"","Андрей: «Может быть. Только если все так будут думать, мы друг другу хуже заражённых станем».","Андрей: «Я стараюсь. Но каждый раз думаю, сколько воды останется мне самому».","Андрей: «Тоже вариант. Но иногда человек приходит не торговаться, а присмотреть, что можно забрать».","Андрей: «Спасибо. Хотелось бы думать, что достаточно».","Андрей: «Может, так безопаснее. Но страшно однажды самому оказаться по другую сторону закрытой двери».","Джон: «Я встретил женщину с ребёнком в жилом доме. Они тоже не сразу мне поверили».\nАндрей: «И правильно. Я бы на их месте тоже дверь первому встречному не открыл. Надеюсь, у них всё получилось».","Джон: «Я помог Кириллу. Мы тоже не сразу договорились».\nАндрей: «Хорошо, что хотя бы поговорили, прежде чем хвататься за оружие».","Джон: «В магазине я встретил Виктора Павловича и помог ему».\nАндрей: «Интересно, как он там. Передай ему, что в лесу ещё остался хотя бы один упрямец»."};say("Другие выжившие",text[c],scanner);
    }
    private static void ordinary(ForestStories s,WorldStories w,Scanner scanner){
        GameIO.storyMenu("Чего тебе не хватает?","Андрей: «Знаешь, чего мне больше всего не хватает? Нормального кофе. Чтобы с утра сварить и никуда не спешить». Он смеётся: «Самое смешное, что раньше я кофе почти не пил».");
        GameIO.action(1,"Горячего душа");GameIO.action(2,"Музыки");GameIO.action(3,"Безопасного сна");GameIO.action(4,"Нормальной еды — например, пиццы");GameIO.action(5,"Интернета");GameIO.action(0,"Выбрать другую тему");int c=SurvivalSystems.choice(scanner);if(c<1||c>5)return;record(s,w,5,c);
        String[] text={"","Андрей: «Вот! Я тут ведро на солнце ставил. Вода нагрелась, а пока донёс до домика, остыла. Такие теперь у нас технологии».","Андрей: «У меня где-то был старый плеер. Только батареек нет. Найду — будем устраивать концерты для белок».","Андрей: «Это да. Я уже забыл, когда последний раз просыпался не от какого-нибудь шороха».","Андрей: «А я бы две пиццы съел. Только после такого питания уже и первую не осилил бы, наверное».","Андрей: «Да уж. Хотя половина сообщений наверняка была бы рекламой. Даже конец света от неё не спасёт»."};say("Чего тебе не хватает?",text[c],scanner);
    }
    private static void finish(ForestStories s,WorldStories w,Scanner scanner){
        GameIO.storyMenu("Последние угли","Огонь постепенно угасает. Андрей ставит пустые кружки у навеса. «Спасибо, что посидел. Давно я столько не разговаривал. Если мимо идти будешь, заглядывай. Чай почти закончился, но хотя бы костёр разведём».");
        GameIO.action(1,"Обязательно загляну");GameIO.action(2,"Береги себя, Андрей");GameIO.action(3,"Может, ещё встретимся. Если повезёт");GameIO.action(4,"Спасибо за разговор. Мне это было нужно");GameIO.action(5,"В следующий раз кофе принесу");GameIO.action(0,"Пока останусь");int c=SurvivalSystems.choice(scanner);if(c<1||c>5)return;
        s.campfireFinishChoice=c;if(!s.campfireEnded){s.campfireEnded=true;w.advanceMinutes(2);w.note("Последние угли","Джон и Андрей поговорили у костра. К необсуждённым темам можно вернуться позже.");}GameIO.checkpoint();
        String[] answer={"","Обязательно загляну","Береги себя, Андрей","Может, ещё встретимся. Если повезёт","Спасибо за разговор. Мне это было нужно","В следующий раз кофе принесу"};
        say("Последние угли","Джон: «"+answer[c]+"».\n\nДжон поднимается с бревна и поправляет рюкзак. Позади тихо потрескивают угли. Андрей остаётся возле костра, глядя на фотографию. Впереди снова дорога и заражённые. Но сегодня Джон хотя бы ненадолго перестал чувствовать себя единственным человеком в этом мире.",scanner);
    }
}
